/// Kata atau frasa pendek yang disisipkan ke dalam kalimat (`{}`). Cuma diganti kalau SELURUH sisipan persis
/// kata itu, supaya data pemakai yang kebetulan memuat kata yang sama tidak ikut berubah.
pub(crate) static KATA: &[(&str, &str)] = &[
    ("elemen", "elements"),
    ("karakter", "characters"),
    ("kunci", "keys"),
    ("field", "fields"),
    ("key", "keys"),
    ("akhir file", "end of file"),
    ("akhir berkas", "end of file"),
    ("akhir baris", "end of line"),
    ("awal", "start"),
    ("akhir", "end"),
    ("nilai", "value"),
    ("argumen", "arguments"),
    ("tidak ada", "none"),
    ("(tidak ada)", "(none)"),
];

#[cfg(test)]
mod tests {
    use super::TABEL;

    #[test]
    fn pola_diawali_dan_diakhiri_teks_dan_lubangnya_cocok() {
        for (id, en) in TABEL {
            assert!(!id.starts_with("{}") && !id.ends_with("{}"), "pola `{id}` harus diawali dan diakhiri teks");
            let n = id.matches("{}").count();
            let (_, lubang) = super::super::mesin::urai_en_uji(en, n);
            let mut l = lubang.clone();
            l.sort();
            l.dedup();
            assert_eq!(l.len(), n, "`{id}` punya {n} isian, padanannya `{en}` memakai {:?}", lubang);
        }
        let mut kunci: Vec<&str> = TABEL.iter().map(|(id, _)| *id).collect();
        kunci.sort();
        for w in kunci.windows(2) {
            assert_ne!(w[0], w[1], "pola kembar `{}`", w[0]);
        }
    }
}
